INIT_BLOCK = '\nfrom .oracle_certified_research_evidence_collection_session_activation_gate import (\n    EVIDENCE_ENTRY_ACTIVE,\n    EVIDENCE_SESSION_ACTIVE,\n    EVIDENCE_SESSION_POLICY_ID,\n    OracleCertifiedResearchEvidenceCollectionSessionEntry,\n    OracleCertifiedResearchEvidenceCollectionSession,\n    OracleCertifiedResearchEvidenceCollectionSessionActivationGate,\n)\n\n__all__ = [\n    "EVIDENCE_ENTRY_ACTIVE",\n    "EVIDENCE_SESSION_ACTIVE",\n    "EVIDENCE_SESSION_POLICY_ID",\n    "OracleCertifiedResearchEvidenceCollectionSessionEntry",\n    "OracleCertifiedResearchEvidenceCollectionSession",\n    "OracleCertifiedResearchEvidenceCollectionSessionActivationGate",\n] + __all__\n'


def verify_oia026() -> None:
    if not OIA026.exists():
        raise RuntimeError(f"Actual OIA-026 production module missing: {OIA026}")
    source = OIA026.read_text(encoding="utf-8")
    required = [
        'SCHEMA_VERSION = "OIA-026"', 'ENGINE_ID = "OIA-026"',
        'EVIDENCE_MANIFEST_POLICY_ID', 'EVIDENCE_MANIFEST_ISSUED',
        'EVIDENCE_ENTRY_AUTHORIZED', 'source_certification_hash',
        'source_readiness_hash', 'source_session_hash', 'source_activation_hash',
        'source_claim_hash', 'source_dispatch_manifest_hash', 'source_batch_hash',
        'source_certification_entry_hash', 'evidence_entry_hash',
        'authorized_evidence_operations', 'prohibited_operations',
        'read_only_corpus', 'research_execution_allowed',
        'analytic_conclusion_allowed', 'forecast_creation_allowed',
        'qseries_handoff_allowed', 'market_order_creation_allowed',
        'funds_movement_allowed', 'portfolio_mutation_allowed',
    ]
    missing = [token for token in required if token not in source]
    if missing:
        raise RuntimeError(f"Actual OIA-026 production contract mismatch: {missing}")


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.rstrip() + "\n", encoding="utf-8")
    print(f"[OK] FULL REPLACEMENT: {path}")


def update_init() -> None:
    source = INIT.read_text(encoding="utf-8") if INIT.exists() else "__all__ = []\n"
    marker = "from .oracle_certified_research_evidence_collection_session_activation_gate import ("
    if marker not in source:
        source = source.rstrip() + "\n" + INIT_BLOCK
        INIT.write_text(source.rstrip() + "\n", encoding="utf-8")
        print(f"[OK] PACKAGE UPDATED: {INIT}")
    else:
        print(f"[OK] PACKAGE ALREADY CURRENT: {INIT}")


def main() -> int:
    print("=" * 40)
    print(" OIA-027 INSTALLER")
    print(" EVIDENCE COLLECTION SESSION ACTIVATION")
    print(" READ-ONLY COLLECTION AUTHORITY BOUNDARY")
    print("=" * 40)
    verify_oia026()
    print("[OK] Actual OIA-026 evidence manifest contract verified")
    write_full_replacement(PRODUCTION, PRODUCTION_SOURCE)
    write_full_replacement(TEST, TEST_SOURCE)
    update_init()
    py_compile.compile(str(PRODUCTION), doraise=True)
    py_compile.compile(str(TEST), doraise=True)
    py_compile.compile(str(INIT), doraise=True)
    print("[OK] Production, test, and package syntax verified")
    result = subprocess.run([sys.executable, str(TEST)], cwd=str(ROOT), check=False)
    if result.returncode != 0:
        raise SystemExit(result.returncode)
    print("[OK] OIA-027 test executed automatically")
    print()
    print("[DONE] OIA-027 evidence collection session activation gate installed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
